import contextlib,io,runpy,sys,json,time,pathlib
root=pathlib.Path(__file__).resolve().parents[2]
sys.argv=['helper','get_editor_state']
with contextlib.redirect_stdout(io.StringIO()):ns=runpy.run_path(str(root/'Tools/Review/unity_mcp.py'))
def code(source):
 result=ns['rpc']('tools/call',{'name':'execute_code','arguments':{'code':source,'skip_refresh':True}})['result']
 data=json.loads('\n'.join(v.get('text','') for v in result.get('content',[])))
 if result.get('isError') or not data.get('success') or data.get('data',{}).get('logged_error_count',0):raise RuntimeError(data)
 return data.get('data',{}).get('result')
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parent))
import session;session.ensure_scene(code,'Game')
base='var save=UnityEngine.Object.FindFirstObjectByType<CampaignSaveManager>();using var scope=save.SuppressSaving();var campaign=UnityEngine.Object.FindFirstObjectByType<CampaignManager>();var clock=UnityEngine.Object.FindFirstObjectByType<GameClock>();var list=UnityEngine.Object.FindFirstObjectByType<OrderBook>();var cooking=UnityEngine.Object.FindFirstObjectByType<CookingManager>();var business=UnityEngine.Object.FindFirstObjectByType<BusinessView>();var handover=UnityEngine.Object.FindFirstObjectByType<HandoverManager>();var roster=UnityEngine.Object.FindFirstObjectByType<CourierRoster>();'
steps=[
('manual setup','save.StartNewGame();clock.AutomaticTick=false;var recruitment=UnityEngine.Object.FindFirstObjectByType<RecruitmentManager>();var crew=UnityEngine.Object.FindFirstObjectByType<KitchenCrew>();if(!recruitment.Fire(crew.People[0]))throw new Exception("could not arrange manual kitchen");campaign.StartBusiness();UnityEngine.Object.FindFirstObjectByType<OrderSpawner>().enabled=false;cooking.ManualControlEnabled=true;list.AddOrder(new Order("Goal1","マルゲリータ",clock.ElapsedSeconds,120));'),
('ticket click','var ticket=business.GetComponentsInChildren<DragSource>(true).First(s=>s.name=="Ticket_1");ticket.Clicked();if(cooking.BenchJob(0)?.Stage!=PizzaStage.Ticket)throw new Exception("ticket did not reach bench");'),
('dough and sauce','business.ClickTrayFor(DragKind.Dough,Topping.Basil);float coverage=0;for(int y=0;y<16;y++)for(int x=0;x<16;x++)coverage=business.TraceSauce(0,new Vector2((x+.5f)/16,(y+.5f)/16));if(coverage<.7f || !business.CommitSauce(0))throw new Exception("sauce did not reach 70%");'),
('cheese topping oven','business.ClickTrayFor(DragKind.Cheese,Topping.Basil);business.ClickTrayFor(DragKind.Topping,Topping.Basil);business.ClickPizzaOn(0);if(cooking.OvenJob(0)?.Stage!=PizzaStage.Baking)throw new Exception("pizza did not enter oven");'),
('bake band takeout','clock.Advance(cooking.BakeSeconds);business.ClickOvenAt(0);if(!handover.RackOrders.Any() || cooking.PackedByPlayer!=1)throw new Exception("takeout did not pack the pizza at once");'),
('packed box on shelf','if(!business.GetComponentsInChildren<RectTransform>(true).Any(r=>r.name.StartsWith("Box_") && r.GetComponentsInParent<RectTransform>(true).Any(p=>p.name=="WarmingShelf")))throw new Exception("packed box not stocked on the warming shelf");'),
('open dispatch','business.ShowZone(ShopZone.Dispatch,true);'),
('lane select','var lane=business.GetComponentsInChildren<DragSource>(true).First(s=>s.name=="Lane_Aoi");lane.Clicked();if(roster.SelectedPerson!=roster.People[0])throw new Exception("lane selection failed");'),
('drop ticket into lane','var zone=business.GetComponentsInChildren<DropZone>(true).First(z=>z.name=="Lane_Aoi");var o=list.Orders.First();var payload=new DragPayload{Kind=DragKind.Box,Order=o};if(!zone.Accepts(payload))throw new Exception("lane refuses a baked ticket");zone.Dropped(payload);if(handover.BagOf(roster.People[0]).Count!=1)throw new Exception("order did not enter the lane");'),
('order countdown and no handover tab','var label=business.GetComponentsInChildren<TMPro.TMP_Text>(true).First(t=>t.name=="Countdown" && t.transform.parent.name=="Order_1");if(!label.text.Contains("目安まで"))throw new Exception("countdown missing");var tab=business.GetComponentsInChildren<StickerButton>(true).First(b=>b.name=="Zone1");if(tab.GetComponent<CanvasGroup>().alpha!=0)throw new Exception("handover tab visible");'),
('map zoom button','var cam=Camera.main;float before=cam.orthographicSize;business.GetComponentsInChildren<UnityEngine.UI.Button>(true).First(b=>b.name=="ZoomIn").onClick.Invoke();if(cam.orthographicSize>=before)throw new Exception("zoom did not change view");'),
('road width remains readable','float px=Camera.main.orthographicSize*2/Camera.main.pixelHeight;foreach(var edge in UnityEngine.Object.FindObjectsByType<EdgeView>(FindObjectsSortMode.None)){if(edge.GetComponent<LineRenderer>().startWidth>UITheme.Active.mapRoadMaxPixels*px+.001f)throw new Exception("road exceeded pixel cap");}business.FitMap();'),
('automatic round trip','business.SyncRoute();var planner=UnityEngine.Object.FindFirstObjectByType<DeliveryPlanner>();var map=UnityEngine.Object.FindFirstObjectByType<MapManager>();if(planner.SelectedPlan==null || planner.Route.CurrentNodeId!=map.StoreNodeId)throw new Exception("lane did not produce a round trip");'),
('handle waypoint reroutes','var planner=UnityEngine.Object.FindFirstObjectByType<DeliveryPlanner>();var map=UnityEngine.Object.FindFirstObjectByType<MapManager>();var before=planner.Route.NodeIds.ToList();var via=map.Nodes.First(n=>!n.IsStore && !before.Contains(n.Id));if(!business.SetWaypoint(roster.People[0],0,via.Id) || !planner.Route.HasVisited(via.Id) || planner.SelectedPlan==null)throw new Exception("waypoint not on route");business.ResetRoute(roster.People[0]);if(planner.Route.HasVisited(via.Id))throw new Exception("reset kept the waypoint");'),
('road waypoint reroutes','var planner=UnityEngine.Object.FindFirstObjectByType<DeliveryPlanner>();var map=UnityEngine.Object.FindFirstObjectByType<MapManager>();var before=planner.Route.EdgeIds.ToList();var road=map.Edges.Where(e=>!before.Contains(e.Id)).FirstOrDefault(e=>business.SetWaypointRoad(roster.People[0],0,e.Id) && planner.Route.EdgeIds.Contains(e.Id));if(road==null || planner.SelectedPlan==null)throw new Exception("road waypoint not on route");business.ResetRoute(roster.People[0]);'),
('drag the red line onto another road','var planner=UnityEngine.Object.FindFirstObjectByType<DeliveryPlanner>();var map=UnityEngine.Object.FindFirstObjectByType<MapManager>();var cam=Camera.main;Vector2 P(string id)=>map.Nodes.First(n=>n.Id==id).Position;Vector2 Mid(MapEdge e){var m=(P(e.NodeAId)+P(e.NodeBId))/2;if(e.RoadType==RoadType.Backstreet){var d=(P(e.NodeBId)-P(e.NodeAId)).normalized;m+=new Vector2(-d.y,d.x)*.35f;}return cam.WorldToScreenPoint(m);}var before=planner.Route.EdgeIds.ToList();var grab=Mid(map.GetEdge(before[1]));string moved=null;foreach(var e in map.Edges.Where(e=>!before.Contains(e.Id))){business.PointerDown(grab);business.PointerMove(grab+new Vector2(20,0));business.PointerMove(Mid(e));business.PointerUp(Mid(e));if(planner.Route.EdgeIds.Contains(e.Id)){moved=e.Id;break;}business.ResetRoute(roster.People[0]);}if(moved==null)throw new Exception("dragging the route changed nothing: "+business.InputTrace);if(planner.SelectedPlan==null)throw new Exception("dragged route is not a round trip");business.ResetRoute(roster.People[0]);'),
('lane departure','var depart=business.GetComponentsInChildren<UnityEngine.UI.Button>(true).First(b=>b.name=="Depart_Aoi");depart.onClick.Invoke();if(roster.People[0].CurrentTrip==null)throw new Exception("courier did not depart");'),
('in-flight countdown','var countdown=business.GetComponentsInChildren<TMPro.TMP_Text>(true).First(t=>t.name=="Countdown" && t.transform.parent.name=="Order_1");var state=countdown.transform.parent.Find("State/Text").GetComponent<TMPro.TMP_Text>();if(!countdown.text.Contains("到着まで") || state.text!="配達中")throw new Exception("arrival countdown missing: "+countdown.text+" / "+state.text);'),
('delivery return settlement','clock.Advance(clock.BusinessDuration+1000);if(clock.Phase!=DayPhase.Ended || UnityEngine.Object.FindFirstObjectByType<DayStats>().DeliveredCount!=1)throw new Exception("delivery or settlement did not complete");')]
steps.extend([
('late order setup','save.StartNewGame();clock.AutomaticTick=false;campaign.StartBusiness();UnityEngine.Object.FindFirstObjectByType<OrderSpawner>().enabled=false;list.AddOrder(M7Validation.ReadyOrder("Goal1","遅延テスト",0,5));business.ShowZone(ShopZone.Dispatch,true);clock.Advance(6);'),
('grace countdown visible','var label=business.GetComponentsInChildren<TMPro.TMP_Text>(true).First(t=>t.name=="Countdown" && t.transform.parent.name=="Order_1");if(!label.text.Contains("遅れ") || !label.text.Contains("受付あと"))throw new Exception("grace countdown missing");clock.Advance(19);'),
('cancel reason stays visible','var label=business.GetComponentsInChildren<TMPro.TMP_Text>(true).First(t=>t.name=="Countdown" && t.transform.parent.name=="Order_1");if(!label.text.Contains("キャンセル"))throw new Exception("cancelled order disappeared without explanation");'),
('opening orders and shelf stock','UnityEngine.Object.FindFirstObjectByType<OrderSpawner>().enabled=true;save.StartNewGame();clock.AutomaticTick=false;campaign.StartBusiness();clock.Advance(.01f);if(list.OrderCount!=3)throw new Exception("orders at opening: "+list.OrderCount);UnityEngine.Object.FindFirstObjectByType<OrderSpawner>().enabled=false;list.AddOrder(M7Validation.ReadyOrder("Goal2","棚の箱",clock.ElapsedSeconds,120));business.ShowZone(ShopZone.Kitchen,true);'),
('kitchen has no courier handover','if(business.GetComponentsInChildren<RectTransform>(true).Any(r=>r.name=="CounterStrip" || r.name.StartsWith("Token_")))throw new Exception("couriers still shown in the kitchen");'),
('promise slider','var slider=business.GetComponentsInChildren<UnityEngine.UI.Slider>(true).First(s=>s.name=="PromiseSlider");var spawner=UnityEngine.Object.FindFirstObjectByType<OrderSpawner>();if(Mathf.Abs(spawner.PromiseSeconds-60)>.01f)throw new Exception("range update changed the promise: "+spawner.PromiseSeconds);slider.value=90;if(Mathf.Abs(spawner.PromiseSeconds-90)>.01f)throw new Exception("slider did not set the promise");if(slider.minValue!=Mathf.Ceil(spawner.MinimumPromiseSeconds))throw new Exception("slider minimum is not the physical minimum");spawner.SetPromiseSeconds(60);'),
('menu is a modal','var menu=UnityEngine.Object.FindFirstObjectByType<GameMenu>();menu.ShowMenu();var card=business.transform.parent.GetComponentsInChildren<RectTransform>(true).First(r=>r.name=="ModalCard" && r.GetComponentsInChildren<StickerButton>(true).Any(b=>b.name=="ModalResume"));var veil=card.parent.GetComponent<UnityEngine.UI.Image>();if(!menu.MenuOpen || veil.color.a<.3f || veil.color.a>.8f)throw new Exception("menu is not a see-through modal");menu.Resume();if(menu.MenuOpen)throw new Exception("menu did not close");'),
('records stay suppressed','var before=save.RecordsSummary;save.RecordDay(999,99999,99999,9999);if(save.RecordsSummary!=before)throw new Exception("suppressed records changed");'),
('bake estimate setup','business.ShowZone(ShopZone.Dispatch,true);'),
('bake estimate on the dispatch list','var waiting=list.Orders.First(o=>!o.IsReady);if(!cooking.ReadyIn(waiting).HasValue)throw new Exception("no estimate for a staff order");var row=business.GetComponentsInChildren<TMPro.TMP_Text>(true).First(t=>t.name=="Detail" && t.transform.parent.name=="Order_"+business.Number(waiting));if(!row.text.Contains("焼き上がり 約"))throw new Exception("bake time not shown: "+row.text);'),
('lane quick status','var lane=business.GetComponentsInChildren<RectTransform>(true).First(r=>r.name=="Lane_Aoi");if(lane.Find("Stamina")==null || lane.Find("Driving")==null || lane.Find("Knowledge")==null)throw new Exception("courier status missing in lane");')])
results=[]
try:
 for title,action in steps:
  value=code(base+action+'return "PASS: '+title+'";');results.append(value);print(value,flush=True);time.sleep(.4)
finally:
 code(base+'UnityEngine.Object.FindFirstObjectByType<OrderSpawner>().enabled=true;save.StartNewGame();clock.AutomaticTick=false;return "normal save protected, spawner restored, review finished";')
(root/'Docs/Handoff/Shop_Manual_UI.json').write_text(json.dumps(results,ensure_ascii=False,indent=2))

session.finish(code)
